// The shop's pack art (shop and lab plan, F5; the approved F0 mockup). Every product draws its 84×84 sprite of the
// Aseprite set (F5c, approved by the owner: art/shop/tienda-packs.aseprite, generated by art/shop/gen/) from one strip:
// coins 1–6, dust 1–6, components 1–6, then the welcome pack and the three kits. Each sits on its currency's glow with
// sparkles that twinkle (more with the size). Deterministic: the sparkles' places come from a fixed hash, only their
// phase follows the time.

export type PackArt = { kind: 'coins' | 'dust' | 'components' | 'bundle'; tier: number };

/** The sprites' side, in pixels (shown at 2× in the cards and 3× in the featured offer). */
export const SPRITE = 84;
const CURRENCY_ORDER = ['coins', 'dust', 'components'] as const;
/** The bundles' frames, after the currencies': the welcome pack, then the kits by size (arranque, explorador, comandante). */
const BUNDLE_FRAME: Record<number, number> = { 1: 18, 3: 19, 4: 20, 5: 21 };

/** The strip as a served file, never inlined (it stays out of the bundle). */
const STRIP = Object.values(import.meta.glob<string>('./packs.png', { eager: true, query: '?no-inline', import: 'default' }))[0];
let strip: HTMLImageElement | null = null;
const onStrip = new Set<() => void>();

/** The strip once it has loaded (null until then); it loads on first use. */
function packStrip(): HTMLImageElement | null {
  if (!STRIP || typeof Image === 'undefined') return null;
  if (!strip) {
    strip = new Image();
    strip.decoding = 'async';
    strip.onload = () => {
      for (const f of onStrip) f();
      onStrip.clear();
    };
    strip.src = STRIP;
  }
  return strip.complete && strip.naturalWidth > 0 ? strip : null;
}

/** Calls `f` once the strip has loaded (at once if it already has); returns how to stop waiting. */
export function whenStrip(f: () => void): () => void {
  if (packStrip()) {
    f();
    return () => undefined;
  }
  onStrip.add(f);
  return () => onStrip.delete(f);
}

/** The frame of a product's art in the strip. */
export function spriteFrame(art: PackArt): number {
  if (art.kind === 'bundle') return BUNDLE_FRAME[art.tier] ?? BUNDLE_FRAME[3]!;
  return CURRENCY_ORDER.indexOf(art.kind) * 6 + art.tier;
}

const GLOW: Record<PackArt['kind'], string> = { coins: '255,201,74', dust: '155,134,255', components: '69,227,166', bundle: '255,107,122' };

/** The art of a product's `art` id: `coins-3`, `dust-1`, `components-6`, or a bundle (the welcome pack, a kit by size). */
export function artOf(art: string, kind: 'pack' | 'bundle' | 'welcome' | 'cosmetic'): PackArt {
  const m = /^(coins|dust|components)-([1-6])$/.exec(art);
  if (m) return { kind: m[1] as PackArt['kind'], tier: Number(m[2]) - 1 };
  if (kind === 'welcome') return { kind: 'bundle', tier: 1 };
  const big = /comandante|best|3$/.test(art) ? 5 : /explorador|2$/.test(art) ? 4 : 3;
  return { kind: 'bundle', tier: big };
}

const px = (c: CanvasRenderingContext2D, x: number, y: number, color: string) => {
  c.fillStyle = color;
  c.fillRect(x | 0, y | 0, 1, 1);
};
const hash = (i: number, k: number) => (((Math.sin(i * k) * 43758.5453) % 1) + 1) % 1;

/** Paints one frame of a pack (`t` in ms moves only the sparkles; 0 is a still frame). */
export function paintPack(canvas: HTMLCanvasElement, art: PackArt, t = 0): void {
  const c = canvas.getContext('2d');
  if (!c) return;
  const W = canvas.width;
  const H = canvas.height;
  const { kind, tier } = art;
  c.clearRect(0, 0, W, H);
  const cx = W / 2;
  const glow = GLOW[kind];
  const g = c.createRadialGradient(cx, H * 0.55, 2, cx, H * 0.55, W * (0.25 + tier * 0.05));
  g.addColorStop(0, `rgba(${glow},${0.25 + tier * 0.06})`);
  g.addColorStop(1, `rgba(${glow},0)`);
  c.fillStyle = g;
  c.fillRect(0, 0, W, H);
  const img = packStrip();
  if (img) {
    c.imageSmoothingEnabled = false;
    c.drawImage(img, spriteFrame(art) * SPRITE, 0, SPRITE, SPRITE, 0, 0, W, H);
  }
  const sparks = 2 + tier * 2;
  for (let i = 0; i < sparks; i++) {
    const phase = (t / 400 + i * 1.7) % 3;
    if (phase > 1) continue;
    const x = hash(i, 12.9898) * (W - 8) + 4;
    const y = hash(i, 78.233) * (H * 0.6) + 3;
    const color = phase < 0.5 ? '#ffffff' : `rgb(${glow})`;
    px(c, x, y, color);
    if (phase > 0.25 && phase < 0.75) {
      px(c, x - 1, y, color);
      px(c, x + 1, y, color);
      px(c, x, y - 1, color);
      px(c, x, y + 1, color);
    }
  }
}
